import React, { useContext, useLayoutEffect, useRef } from 'react';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { useMergeRefs } from '../../../core/hooks/useMergeRefs.js';
import { uuidv4 } from '../../../core/utils/uuidv4.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { useThrottledResizeObserver } from '../../core/hooks/useThrottledResizeObserver.js';
import { useGlobalFontSize } from '../../single-value-grid/hooks/use-global-font-size.js';
import {
  FONT_HEIGHT_RATIO,
  LABEL_FONT_CSS_TOKEN,
  LABEL_FONT_SIZE,
} from '../constants.js';
import { SingleValueContext } from '../contexts/single-value.context.js';
import { useFontSizeForContainer } from '../hooks/use-font-size-for-container.js';

interface LabelAreaProps {
  fontSize: number;
}

const LabelArea = /* @__PURE__ */ styled(Flex).attrs<LabelAreaProps>(
  ({ fontSize }) => ({
    style: {
      [LABEL_FONT_CSS_TOKEN]: fontSize,
    },
  }),
)<LabelAreaProps>({
  gridArea: 'label',
  whiteSpace: 'nowrap',
  overflow: 'hidden',
  fontSize: `calc(${LABEL_FONT_SIZE} * 1px)`,
  color: Colors.Text.Neutral.Subdued,
});

export const Label = () => {
  const { label, alignment } = useContext(SingleValueContext);

  const ref = useRef<HTMLDivElement>();

  const { refCallback, width = 0, height = 0 } = useThrottledResizeObserver();

  const mergedRef = useMergeRefs([refCallback, ref]);

  const preferredFontSize = useFontSizeForContainer({
    container: { width, height: height * FONT_HEIGHT_RATIO },
    text: label ?? '',
    element: ref.current,
  });

  const id = useRef<string>(uuidv4());
  const { updateLabelFontSize } = useGlobalFontSize();

  useLayoutEffect(() => {
    if (height && width) {
      updateLabelFontSize?.(id.current, preferredFontSize);
    }
  }, [height, width, preferredFontSize]);

  return (
    <LabelArea
      ref={mergedRef}
      justifyContent={alignment}
      alignItems={'center'}
      fontSize={preferredFontSize}
    >
      {label !== undefined && (
        <div data-testid="single-value-chart-label">{label}</div>
      )}
    </LabelArea>
  );
};
Label['displayName'] = 'SingleValue.Label';
